$ErrorActionPreference = "Stop"

$ProjectRoot = "D:\nctb-study-companion-starter"
$QuizPage = Join-Path $ProjectRoot "app\quiz\page.tsx"
$GenerateRoute = Join-Path $ProjectRoot "app\api\quiz\generate\route.ts"

if (-not (Test-Path -LiteralPath (Join-Path $ProjectRoot "package.json"))) {
    throw "Project not found at $ProjectRoot"
}

if (-not (Test-Path -LiteralPath $QuizPage)) {
    throw "Quiz page not found: $QuizPage"
}

if (-not (Test-Path -LiteralPath $GenerateRoute)) {
    throw "Quiz generator not found: $GenerateRoute"
}

Set-Location $ProjectRoot

$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $ProjectRoot "backups\model-quiz-frontend-$Timestamp"
[System.IO.Directory]::CreateDirectory($BackupDirectory) | Out-Null

Copy-Item -LiteralPath $QuizPage -Destination (Join-Path $BackupDirectory "quiz-page.tsx") -Force
Copy-Item -LiteralPath $GenerateRoute -Destination (Join-Path $BackupDirectory "generate-route.ts") -Force

$FrontendBase64 = @'

'@

$RouteBase64 = @'

'@

[System.IO.File]::WriteAllBytes(
    $QuizPage,
    [System.Convert]::FromBase64String(($FrontendBase64 -replace "\s", ""))
)

[System.IO.File]::WriteAllBytes(
    $GenerateRoute,
    [System.Convert]::FromBase64String(($RouteBase64 -replace "\s", ""))
)

Write-Host ""
Write-Host "Bangladesh model-question frontend installed." -ForegroundColor Green
Write-Host "Backup created at:" -ForegroundColor Cyan
Write-Host $BackupDirectory
Write-Host ""
Write-Host "Updated:" -ForegroundColor Cyan
Write-Host "  app\quiz\page.tsx"
Write-Host "  app\api\quiz\generate\route.ts"
Write-Host ""
Write-Host "Next commands:" -ForegroundColor Yellow
Write-Host "  Remove-Item .next -Recurse -Force -ErrorAction SilentlyContinue"
Write-Host "  npm run build"
Write-Host "  npm run dev"
